-- 鹊桥业务后端 · 表结构基线（由 Hibernate 元数据导出，与全部实体一一对应）
-- Flyway 版本：1。启用方式：--spring.profiles.active=migrate
-- 说明：以下 DDL 在 H2(MySQL 兼容模式) 与 MySQL 8 下均可用；新增实体请追加 V2__*.sql 而非修改本文件。

create table t_activity (act_date date, capacity integer, expected_pairs integer, female integer, hero boolean, male integer, price float(53), revenue float(53), signed integer, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, act_time varchar(255), agent varchar(255), city varchar(255), description TEXT, place varchar(255), status varchar(255), tags varchar(255), title varchar(255), weekday varchar(255), primary key (id));
create table t_activity_signup (amount float(53), paid boolean, id bigint generated by default as identity, signed_at timestamp(6), activity_id varchar(255), gender varchar(255), member_id varchar(255), member_name varchar(255), phone varchar(255), status varchar(255), primary key (id));
create table t_agent (capacity integer, join_date date, member_count integer, month_match integer, month_revenue float(53), rating float(53), success_rate integer, created_at timestamp(6), id varchar(64) not null, avatar_bg varchar(255), level varchar(255), name varchar(255), phone varchar(255), region varchar(255), status varchar(255), primary key (id));
create table t_ai_feedback (created_at timestamp(6), id bigint generated by default as identity, action varchar(16), scene varchar(32), item_id varchar(64), operator varchar(64), operator_id varchar(64), dimensions varchar(255), reason TEXT, primary key (id));
create table t_audit_task (age integer, paid boolean, handled_at timestamp(6), submitted_at timestamp(6), id varchar(64) not null, agent varchar(255), applicant varchar(255), change_field varchar(255), change_from varchar(255), change_to varchar(255), gender varchar(255), handler varchar(255), material TEXT, member_id varchar(255), pay_text varchar(255), reason TEXT, status varchar(255), type varchar(255), urgency varchar(255), primary key (id));
create table t_automation_rule (enabled boolean not null, last_created integer, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, cron varchar(255), desc TEXT, last_run_at varchar(255), name varchar(255), params TEXT, scope varchar(255), primary key (id));
create table t_blacklist (until date, created_at timestamp(6), id varchar(64) not null, member_id varchar(255), member_name varchar(255), operator varchar(255), reason TEXT, status varchar(255), primary key (id));
create table t_calendar_event (event_date date, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, agent varchar(255), dedup_key varchar(255), end_time varchar(255), event_type varchar(255), member_ids varchar(255), member_names varchar(255), pair_id varchar(255), place varchar(255), remark TEXT, start_time varchar(255), status varchar(255), title varchar(255), primary key (id));
create table t_channel_ledger (amount float(53), created_at timestamp(6), paid_at timestamp(6), id varchar(64) not null, channel varchar(255), order_id varchar(255), order_no varchar(255), status varchar(255), trade_no varchar(255), primary key (id));
create table t_city_partner (share_rate float(53), start_date date, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, city varchar(255), owner_agent_id varchar(255), owner_agent_name varchar(255), phone varchar(255), remark TEXT, status varchar(255), tier varchar(255), primary key (id));
create table t_commission_record (amount float(53), order_amount float(53), rate float(53), created_at timestamp(6), settled_at timestamp(6), withdrawn_at timestamp(6), id varchar(64) not null, agent_id varchar(255), agent_name varchar(255), batch_no varchar(255), order_id varchar(255), pair_id varchar(255), status varchar(255), type varchar(255), primary key (id));
create table t_community_membership (active_from timestamp(6), active_to timestamp(6), created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, city varchar(255), member_id varchar(255), member_name varchar(255), order_id varchar(255), status varchar(255), tier_id varchar(255), tier_level varchar(255), primary key (id));
create table t_community_tier (capacity integer, member_count integer, price float(53), sort_order integer, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, benefits TEXT, city varchar(255), level varchar(255), product_id varchar(255), status varchar(255), primary key (id));
create table t_consent_record (accepted_at timestamp(6), id varchar(64) not null, channel varchar(255), doc_type varchar(255), member_id varchar(255), member_name varchar(255), version varchar(255), primary key (id));
create table t_conversation (online boolean, unread integer, created_at timestamp(6), last_at timestamp(6), id varchar(64) not null, agent varchar(255), avatar_bg varchar(255), dedup_key varchar(255), kind varchar(255), member_id varchar(255), name varchar(255), preview varchar(255), time_ago varchar(255), primary key (id));
create table t_coupon (amount float(53), created_at timestamp(6), expire_at timestamp(6), updated_at timestamp(6), used_at timestamp(6), id varchar(64) not null, code varchar(255) unique, member_id varchar(255), member_name varchar(255), order_id varchar(255), source_id varchar(255), source_type varchar(255), status varchar(255), type varchar(255), primary key (id));
create table t_crm_follow (created_at timestamp(6), id bigint generated by default as identity, content TEXT, follow_type varchar(255), lead_id varchar(255), operator varchar(255), primary key (id));
create table t_crm_lead (age integer, cost float(53), star boolean, stay_days integer, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, agent varchar(255), campaign_id varchar(255), channel varchar(255), fresh varchar(255), fresh_text varchar(255), gender varchar(255), level varchar(255), member_id varchar(255), member_name varchar(255), name varchar(255), next_action varchar(255), phone varchar(255), referrer_member_id varchar(255), referrer_name varchar(255), remark TEXT, source varchar(255), stage varchar(255), primary key (id));
create table t_doc_template (updated_at timestamp(6), id varchar(64) not null, content TEXT, title varchar(255), type varchar(255), updated_by varchar(255), version varchar(255), primary key (id));
create table t_finance_order (amount float(53), coupon_amount float(53), created_at timestamp(6), paid_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, agent varchar(255), biz_type varchar(255), channel varchar(255), coupon_id varchar(255), member_id varchar(255), member_name varchar(255), order_no varchar(255), order_type varchar(255), product_id varchar(255), product_name varchar(255), refund_reason varchar(255), remark varchar(255), status varchar(255), trade_no varchar(255), trade_time varchar(255), primary key (id));
create table t_follow_up (next_follow_up date, created_at timestamp(6), id varchar(64) not null, agent varchar(255), content TEXT, member_id varchar(255), outcome varchar(255), type varchar(255), primary key (id));
create table t_market_channel (cost float(53), created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, category varchar(255), code varchar(255), name varchar(255), owner varchar(255), remark TEXT, status varchar(255), primary key (id));
create table t_member (age integer, expire date, height integer, last_follow_up date, match_count integer, success_rate integer, verified boolean, verify_asset boolean, verify_education boolean, verify_real_name boolean, created_at timestamp(6), updated_at timestamp(6), verify_asset_at timestamp(6), verify_education_at timestamp(6), verify_real_name_at timestamp(6), id varchar(64) not null, agent varchar(255), avatar_bg varchar(255), bio TEXT, car varchar(255), city varchar(255), education varchar(255), feedback varchar(255), gender varchar(255), has_child varchar(255), hometown varchar(255), house varchar(255), income varchar(255), job varchar(255), last_active varchar(255), level varchar(255), marriage varchar(255), name varchar(255), phone varchar(255), requirement TEXT, status varchar(255), tags varchar(255), primary key (id));
create table t_member_report (created_at timestamp(6), handled_at timestamp(6), id varchar(64) not null, content TEXT, handle_note TEXT, handler varchar(255), reporter_id varchar(255), reporter_name varchar(255), status varchar(255), target_member_id varchar(255), target_name varchar(255), type varchar(255), primary key (id));
create table t_merchant_order (amount float(53), commission_amount float(53), commission_rate float(53), created_at timestamp(6), deal_at timestamp(6), settled_at timestamp(6), id varchar(64) not null, agent varchar(255), category varchar(255), member_id varchar(255), member_name varchar(255), merchant_id varchar(255), merchant_name varchar(255), note TEXT, pair_id varchar(255), status varchar(255), primary key (id));
create table t_message (read_flag boolean, created_at timestamp(6), id bigint generated by default as identity, content TEXT, conversation_id varchar(255), msg_type varchar(255), sender varchar(255), primary key (id));
create table t_operation_log (created_at timestamp(6), id bigint generated by default as identity, action varchar(255), detail TEXT, ip varchar(255), target varchar(255), user_id varchar(255), user_name varchar(255), primary key (id));
create table t_pair (score integer, created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, agent varchar(255), female_id varchar(255), female_name varchar(255), female_response varchar(255), female_response_kind varchar(255), male_id varchar(255), male_name varchar(255), male_response varchar(255), male_response_kind varchar(255), note TEXT, reason TEXT, stage varchar(255), status varchar(255), primary key (id));
create table t_partner_merchant (commission_rate float(53), created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, category varchar(255), city varchar(255), contact varchar(255), name varchar(255), phone varchar(255), remark TEXT, status varchar(255), primary key (id));
create table t_pay_reconcile (channel_amount float(53), diff float(53), local_amount float(53), matched boolean, reconcile_date date, created_at timestamp(6), id varchar(64) not null, channel varchar(255), note varchar(255), order_id varchar(255), order_no varchar(255), trade_no varchar(255), primary key (id));
create table t_referral (order_amount float(53), reward_amount float(53), converted_at timestamp(6), created_at timestamp(6), rewarded_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, operator varchar(255), order_id varchar(255), referee_lead_id varchar(255), referee_member_id varchar(255), referee_name varchar(255), referee_phone varchar(255), referrer_id varchar(255), referrer_name varchar(255), referrer_type varchar(255), remark TEXT, reward_type varchar(255), status varchar(255), primary key (id));
create table t_report_record (created_at timestamp(6), id varchar(64) not null, category varchar(255), exported_at varchar(255), file_format varchar(255), file_path varchar(255), file_size varchar(255), name varchar(255), operator varchar(255), range_text varchar(255), status varchar(255), primary key (id));
create table t_risk_event (handled boolean, score integer, created_at timestamp(6), handled_at timestamp(6), id varchar(64) not null, detail TEXT, handle_note TEXT, handler varchar(255), member_id varchar(255), member_name varchar(255), type varchar(255), primary key (id));
create table t_service_product (duration_days integer, price float(53), created_at timestamp(6), id varchar(64) not null, benefits TEXT, category varchar(255), name varchar(255), status varchar(255), primary key (id));
create table t_setting (updated_at timestamp(6), id varchar(64) not null, category varchar(255), label varchar(255), setting_type varchar(255), setting_value TEXT, primary key (id));
create table t_success_story (public_visible boolean, views integer, created_at timestamp(6), published_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, age_tag varchar(255), author varchar(255), city_tag varchar(255), content TEXT, cover varchar(255), female_alias varchar(255), male_alias varchar(255), pair_id varchar(255), status varchar(255), tags varchar(255), title varchar(255), primary key (id));
create table t_sys_user (created_at timestamp(6), last_login_at timestamp(6), id varchar(64) not null, agent_id varchar(255), avatar varchar(255), avatar_bg varchar(255), email varchar(255), name varchar(255), password varchar(255), phone varchar(255), role varchar(255), status varchar(255), username varchar(255), primary key (id));
create table t_verify_task (created_at timestamp(6), updated_at timestamp(6), id varchar(64) not null, channel varchar(255), member_id varchar(255), member_name varchar(255), operator varchar(255), raw_proof TEXT, result TEXT, status varchar(255), type varchar(255), primary key (id));
